import { useState } from 'react';
import { Button, List, Typography, message, Checkbox, Space, Empty, Tag } from 'antd';
import dayjs from 'dayjs';
import DiffEditor from '../components/editors/DiffEditor';
import { callAction } from '../api/client';

export default function ChangeSetApply() {
  const [changeSets, setChangeSets] = useState([]);
  const [activeIndex, setActiveIndex] = useState(null);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(false);

  async function fetchLatest() {
    setLoading(true);
    try {
      const res = await callAction('/api/change-sets/fetch-latest', 'POST');
      const sets = res.changeSets || [];
      setChangeSets(sets);
      if (sets.length === 1) {
        openChangeSet(sets, 0);
      } else {
        setActiveIndex(null);
        setSelected({});
      }
      message.success(sets.length ? 'Fetched. ' + sets.length + ' change set(s) pending.' : 'Fetched. Nothing pending.');
    } catch (e) {
      message.error('Fetch failed: ' + (e && e.message ? e.message : e));
    } finally {
      setLoading(false);
    }
  }

  function openChangeSet(sets, index) {
    const items = sets[index].items;
    const sel = {};
    items.forEach((_, i) => { sel[i] = true; });
    setSelected(sel);
    setActiveIndex(index);
  }

  function formatWhen(cs) {
    const at = cs.generatedAt || cs.createdAt;
    return at ? dayjs(at).format('YYYY-MM-DD HH:mm') : 'Unknown date';
  }

  function formatWho(cs) {
    return cs.createdByName || cs.createdByEmail || 'Unknown user';
  }

  const active = activeIndex != null ? changeSets[activeIndex] : null;

  async function apply() {
    if (!active) return;
    const records = active.items.filter((_, i) => selected[i]);
    if (!records.length) { message.warning('Nothing selected'); return; }
    setLoading(true);
    try {
      await callAction('/api/change-sets/apply', 'POST', { records });
      message.success('Applied ' + records.length + ' record(s).');
      const remaining = changeSets.filter((_, i) => i !== activeIndex);
      setChangeSets(remaining);
      setActiveIndex(null);
      setSelected({});
    } catch (e) {
      message.error('Apply failed: ' + (e && e.message ? e.message : e));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={{ padding: 24 }}>
      <Space style={{ marginBottom: 16 }}>
        <Button onClick={fetchLatest} loading={loading}>Fetch Latest</Button>
        {active && (
          <Button type="primary" onClick={apply} disabled={!active.items.length} loading={loading}>
            Apply Selected
          </Button>
        )}
        {active && changeSets.length > 1 && (
          <Button onClick={() => { setActiveIndex(null); setSelected({}); }}>Back to change sets</Button>
        )}
      </Space>

      {!active && changeSets.length === 0 && (
        <Empty description="No pending change sets. Click Fetch Latest to check." />
      )}

      {!active && changeSets.length > 0 && (
        <List
          bordered
          dataSource={changeSets}
          renderItem={(cs, i) => (
            <List.Item
              actions={[<Button key="review" onClick={() => openChangeSet(changeSets, i)}>Review</Button>]}
            >
              <List.Item.Meta
                title={cs.name}
                description={
                  <Space size="small" wrap>
                    <Tag>{cs.items.length} record{cs.items.length === 1 ? '' : 's'}</Tag>
                    <Typography.Text type="secondary">{formatWhen(cs)}</Typography.Text>
                    <Typography.Text type="secondary">by {formatWho(cs)}</Typography.Text>
                  </Space>
                }
              />
            </List.Item>
          )}
        />
      )}

      {active && (
        <>
          <Typography.Title level={5} style={{ marginTop: 0 }}>
            {active.name}
            <Typography.Text type="secondary" style={{ fontWeight: 'normal', marginLeft: 12 }}>
              {formatWhen(active)} — by {formatWho(active)}
            </Typography.Text>
          </Typography.Title>
          <List
            dataSource={active.items}
            renderItem={(p, i) => (
              <List.Item>
                <div style={{ width: '100%' }}>
                  <Checkbox checked={!!selected[i]}
                    onChange={(e) => setSelected({ ...selected, [i]: e.target.checked })}>
                    <Typography.Text strong>{p.incoming.table}</Typography.Text> — {p.incoming.id}
                    {' '}<Typography.Text type="secondary">({p.incoming.op})</Typography.Text>
                  </Checkbox>
                  <DiffEditor
                    height="240px"
                    language="json"
                    original={JSON.stringify(p.current || {}, null, 2)}
                    modified={JSON.stringify(p.incoming, null, 2)}
                    options={{ readOnly: true }}
                  />
                </div>
              </List.Item>
            )}
          />
        </>
      )}
    </div>
  );
}
